await flushToDisk(entry);
// Re-check after the await: the entry may have been pinned mid-flush.
if (entry.refCount > 0) continue;
cache.entries.delete(entry.key);

// Re-check the live entry after the await: it may have been pinned
// (or replaced) mid-flush — the captured reference can be stale.
const live = cache.entries.get(entry.key);
if (!live || live.refCount > 0) continue;
